// Gusto Roma Cafe — image data (inlined so photos always display,
// regardless of where the HTML file is opened from)
var GR_IMAGES = {
  "hero-pasta": "data:image/jpeg;base64,",
  "pizza-margherita": "data:image/jpeg;base64,",
  "pizza-woodfired": "data:image/jpeg;base64,"
};
(function () {
  "use strict";
  document.querySelectorAll("[data-img]").forEach(function (el) {
    var key = el.getAttribute("data-img");
    if (GR_IMAGES[key]) el.src = GR_IMAGES[key];
  });
})();

// Gusto Roma Cafe — interactions
(function () {
  "use strict";

  // Year in footer
  var year = document.getElementById("year");
  if (year) year.textContent = String(new Date().getFullYear());

  // Mobile menu
  var toggle = document.getElementById("navToggle");
  var menu = document.getElementById("mobileMenu");
  if (toggle && menu) {
    toggle.addEventListener("click", function () {
      var open = toggle.getAttribute("aria-expanded") === "true";
      toggle.setAttribute("aria-expanded", String(!open));
      toggle.classList.toggle("is-open", !open);
      menu.hidden = open;
    });
    menu.addEventListener("click", function (e) {
      if (e.target instanceof HTMLAnchorElement) {
        toggle.setAttribute("aria-expanded", "false");
        toggle.classList.remove("is-open");
        menu.hidden = true;
      }
    });
  }

  // Shrink / state on scroll
  var nav = document.querySelector(".nav");
  var onScroll = function () {
    if (nav) nav.classList.toggle("is-scrolled", window.scrollY > 30);
  };
  onScroll();
  window.addEventListener("scroll", onScroll, { passive: true });

  // Reveal on scroll
  var reveals = document.querySelectorAll(".reveal");
  if ("IntersectionObserver" in window) {
    var io = new IntersectionObserver(
      function (entries) {
        entries.forEach(function (entry) {
          if (entry.isIntersecting) {
            entry.target.classList.add("is-visible");
            io.unobserve(entry.target);
          }
        });
      },
      { threshold: 0.12 }
    );
    reveals.forEach(function (el) {
      io.observe(el);
    });
  } else {
    reveals.forEach(function (el) {
      el.classList.add("is-visible");
    });
  }
})();
